from django.contrib.auth.models import AbstractUser  # Берём готового пользователя Django: у него уже есть логин, пароль и права.
from django.db import models  # Подключаем классы, с помощью которых Python описывает таблицы базы данных.
STATUSES = [  # Список вариантов статуса: слева значение в БД, справа понятная подпись на сайте.
    ("new", "Новая"),  # Этот статус получает только что созданная заявка.
    ("studying", "Идет обучение"),  # Администратор ставит этот статус, когда обучение началось.
    ("completed", "Обучение завершено"),  # После этого статуса пользователь может написать отзыв.
]  # Заканчиваем список статусов.
PAYMENTS = [("cash", "Наличными"), ("phone_transfer", "Переводом по номеру телефона")]  # Допустимы ровно два способа оплаты из задания.
class User(AbstractUser):  # Создаём своего пользователя на основе готового, а не пишем авторизацию самостоятельно.
    full_name = models.CharField("ФИО", max_length=150)  # Добавляем строковое поле ФИО длиной до 150 символов.
    phone = models.CharField("Телефон", max_length=16)  # Телефон храним строкой, поскольку в нём есть скобки и дефисы.
class Course(models.Model):  # Этот класс превращается в таблицу курсов: одна строка таблицы — один курс.
    title = models.CharField("Название", max_length=200, unique=True)  # Названия курсов не должны повторяться: за это отвечает unique=True.
    def __str__(self):  # Этот метод объясняет Django, как показать объект курса в виде текста.
        return self.title  # В выпадающем списке будет название курса, а не техническое «Course object».
class Application(models.Model):  # Этот класс описывает одну заявку на обучение.
    user = models.ForeignKey(User, on_delete=models.PROTECT)  # Связываем заявку с владельцем; пользователя с заявками нельзя удалить случайно.
    course = models.ForeignKey(Course, on_delete=models.PROTECT)  # Связываем заявку с одним курсом; название не копируем в каждую заявку.
    start_date = models.DateField("Дата начала обучения")  # Храним настоящую дату: это позволяет проверить, существует ли такой день.
    payment_method = models.CharField("Способ оплаты", max_length=20, choices=PAYMENTS)  # choices ограничивает выбор двумя способами оплаты.
    status = models.CharField("Статус", max_length=20, choices=STATUSES, default="new", db_index=True)  # Новая заявка начинается с new; индекс помогает фильтровать по статусу.
    review_text = models.TextField("Отзыв", blank=True, default="")  # Отзыв необязателен, поэтому сначала здесь пустая строка.
    class Meta:  # В этом вложенном классе задаём общие настройки таблицы заявок.
        ordering = ["-id"]  # Минус означает убывание: заявки с большим id показываются раньше.
